"""Render docs/FEATURES.md from the feature specs in code (single source of truth).

    .venv/Scripts/python.exe scripts/render_feature_docs.py      # from ml_service/
"""
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))
from fraud_ml import features_claim as fc  # noqa: E402
from fraud_ml import features_provider as fp  # noqa: E402
from fraud_ml.config import N_FOLDS, RARE_CODE_MIN_COUNT, SEED, TEST_SIZE  # noqa: E402


def main() -> None:
    L = ["# Feature dictionary: Kaggle provider-fraud pipeline", "",
         "_Generated by `scripts/render_feature_docs.py` from the specs in `fraud_ml/features_provider.py` and "
         "`fraud_ml/features_claim.py`. Edit the code, not this file._", "",
         "> `PotentialFraud` is a **provider-level** label of **undocumented provenance**. It is the supervised target only, "
         "never an input, and it is not a verified fraud finding.", "",
         "## Prediction time", "",
         "| Model | Unit | Scored when | May use |", "|---|---|---|---|",
         "| Supervised (LR / RF / XGBoost) | Provider | End of the observation period: **provider-level risk, not real-time claim-level fraud** | That provider's claims in the period, its patients' profiles (including year-end annual totals, which fall within the period), and network counts and reference statistics fitted on **training providers only** |",
         "| Isolation Forest (one per claim type) | Claim | When the claim is submitted | The claim's own fields, the patient's clinical profile, that patient's claims on **earlier dates**, reference statistics fitted on training providers. Inpatient and outpatient claims get separate forests and thresholds. |",
         "", f"## Provider-level features ({len(fp.FEATURES)})", "",
         "Size-dependent features (marked ●) are kept for the main model. A volume-only baseline and per-size-group "
         "results will show how much of the signal is just provider size.", "",
         "| # | Feature | Group | Source columns | Calculation | Why | Size |", "|---|---|---|---|---|---|---|"]
    for i, (k, (grp, src, calc, why, vol)) in enumerate(fp.SPEC.items(), 1):
        L.append(f"| {i} | `{k}` | {grp} | {src} | {calc} | {why} | {'●' if vol else ''} |")
    L += ["", f"## Claim-level features for Isolation Forest ({len(fc.FEATURES)})", "",
          "| # | Feature | Source columns | Calculation | Why |", "|---|---|---|---|---|"]
    for i, (k, (src, calc, why)) in enumerate(fc.SPEC.items(), 1):
        L.append(f"| {i} | `{k}` | {src} | {calc} | {why} |")
    L += ["", "## Excluded from all model inputs", "",
          "| Item | Reason |", "|---|---|",
          "| `PotentialFraud`, and anything computed from labels (e.g. the share of a physician's providers that are flagged) | Target leakage. Shared patients and physicians would carry test labels into training. |",
          "| Held-out providers' claims, in any fitted statistic | Network counts, code rarity and reference amounts are fitted on training providers only (per CV fold, then on all development providers) |",
          "| `Race`, `Gender` | Sensitive attributes. Also, their codes are undocumented. These columns are not even loaded. |",
          "| `DOB` / patient age | Sensitive demographic attribute (age); excluded under the project's fairness rule |",
          "| `State`, `County` as categories | Geography can stand in for demographics. Only the *count* of distinct states a provider serves is used. |",
          "| Inpatient `DeductibleAmtPaid` | Constant (1068), so it carries no information |",
          "| Outpatient procedure codes | Present on under 0.1% of outpatient claims |",
          "| Kaggle \"Test\" files | Unlabelled. They share patients with the labelled files. Not used. |",
          "| Patient annual totals, in claim-level features | Year-end values that include later claims (future information) |",
          "| Provider identity or aggregates, in claim-level features | Would turn the claim-level anomaly model into a provider model |",
          "", "## Data-processing approach", "",
          "1. **Loading:** only the needed columns are read; IDs and codes are stored as `category`, numbers as 32-bit. "
          "558k claims take about 106 MB, and the whole preparation runs in about 12 s.",
          "2. **Cleaning (row-by-row, nothing learned):** inpatient and outpatient claims are stacked with a flag; chronic-condition "
          "codes 1/2 become 0/1 (1 = present, by CMS convention, which this dataset doesn't document); renal Y/0 becomes 0/1; negative annual "
          "totals are clipped to 0 and flagged; claim duration and length of stay are derived.",
          "3. **Missing values:** these are structural, so they become counts and flags. Documented defaults: 0 when a provider has no "
          "claims of a type, 400 days when there is no repeat or earlier claim. Nothing is imputed from statistics.",
          "4. **Duplicates:** there are no exact duplicate rows. Near-duplicates and same-day repeats are **features**, not deleted.",
          "5. **Outliers:** kept, since unusual amounts are exactly the signal. Amounts are `log1p`-transformed. Scale-sensitive models get "
          "standardisation fitted inside each training fold.",
          f"6. **Learned statistics** (primary-code frequency, a code counts as rare below {RARE_CODE_MIN_COUNT}; median amount per claim type "
          "and code or DRG) are fitted **on training providers' claims only**, and refitted inside each CV fold.",
          f"7. **Split:** stratified by provider label; {int(TEST_SIZE * 100)}% of providers are held out as the final test set, plus "
          f"{N_FOLDS}-fold stratified CV on the rest (seed {SEED}). Each provider and all its claims sit in exactly one partition. "
          "The test set is not used for selection, tuning or thresholds.",
          "8. **Class imbalance (9.35% positive):** class weights / `scale_pos_weight`; thresholds chosen on out-of-fold predictions; "
          "PR-AUC, recall and precision reported alongside accuracy.", ""]
    out = ROOT / "docs" / "FEATURES.md"
    out.parent.mkdir(exist_ok=True)
    out.write_text("\n".join(L), encoding="utf-8")
    print(f"Wrote {out.relative_to(ROOT)}")


if __name__ == "__main__":
    main()
